    if "type" in raw:
        proto = raw["type"]
        qs = raw.get("query_string", b"")
        if isinstance(qs, bytes):
            qs = qs.decode("utf-8")
        headers = {}
        for k, v in raw.get("headers", []):
            ks = k.decode("latin1") if isinstance(k, bytes) else str(k)
            vs = v.decode("latin1") if isinstance(v, bytes) else str(v)
            headers[ks.lower()] = vs
        return {
            "protocol": proto,
            "method": raw.get("method", "GET").upper(),
            "path": raw.get("path", "/"),
            "query": qs,
            "headers": headers,
        }
