    for k, v in raw.items():
        if k.startswith("HTTP_"):
            headers[k[5:].lower().replace("_", "-")] = v
        elif k == "CONTENT_TYPE":
            headers["content-type"] = v
    return {
        "protocol": "http",
        "method": raw.get("REQUEST_METHOD", "GET").upper(),
        "path": raw.get("PATH_INFO", "/"),
        "query": raw.get("QUERY_STRING", ""),
