class Depends:
    def __init__(self, fn, use_cache=True):
        self.fn = fn
        self.use_cache = use_cache

def resolve_endpoint(endpoint, deps_map: dict):
    cache = {}

    def _resolve(fn, use_cache=True):
        if use_cache and fn in cache:
            return cache[fn]
        kwargs = {}
        for arg_name, dep in deps_map.get(fn, {}).items():
            kwargs[arg_name] = _resolve(dep.fn, dep.use_cache)
        result = fn(**kwargs)
        if use_cache:
            cache[fn] = result
        return result

    return _resolve(endpoint, use_cache=False)

