def fetch_all_batched(items: list, io_cost: int, concurrency: int, runner) -> tuple:
    if not items:
        return ([], 0)
    limit = max(1, concurrency)
    results = []
    total_ticks = 0
    for i in range(0, len(items), limit):
        batch = items[i:i + limit]
        res, ticks = runner(batch, io_cost)
        results.extend(res)
        total_ticks += ticks
    return (results, total_ticks)

