import re

class NoReverseMatch(Exception):
    pass

class URLResolver:
    def __init__(self, app_name: str = ''):
        self.app_name = app_name
        self._routes = []
        self._children = []

    def path(self, pattern: str, handler, name: str = None):
        self._routes.append((pattern, handler, name))

    def include(self, prefix: str, child):
        self._children.append((prefix, child))

    def _iter_routes(self, base_prefix: str = '', ns_parts=None):
        ns = list(ns_parts or [])
        if self.app_name:
            ns.append(self.app_name)
        for pattern, handler, name in self._routes:
            full_pat = '/' + (base_prefix.strip('/') + '/' + pattern.strip('/')).strip('/')
            if pattern.endswith('/') and not full_pat.endswith('/'):
                full_pat += '/'
            if full_pat == '//':
                full_pat = '/'
            full_name = ':'.join(ns + [name]) if name else None
            yield full_pat, handler, full_name
        for prefix, child in self._children:
            sub_prefix = (base_prefix.strip('/') + '/' + prefix.strip('/')).strip('/')
            yield from child._iter_routes(sub_prefix, ns)

    def resolve(self, url: str):
        for pattern, handler, _ in self._iter_routes():
            regex_parts = ['^']
            converters = {}
            pos = 0
            for m in re.finditer(r'<(int|str):([a-zA-Z_][a-zA-Z0-9_]*)>', pattern):
                regex_parts.append(re.escape(pattern[pos:m.start()]))
                conv_type, pname = m.group(1), m.group(2)
                converters[pname] = int if conv_type == 'int' else str
                grp = r'(?P<' + pname + r'>' + (r'\d+' if conv_type == 'int' else r'[^/]+') + ')'
                regex_parts.append(grp)
                pos = m.end()
            regex_parts.append(re.escape(pattern[pos:]) + '$')
            match = re.match(''.join(regex_parts), url)
            if match:
                kw = {k: converters[k](v) for k, v in match.groupdict().items()}
                return handler, kw
        raise NoReverseMatch(f'Cannot resolve {url}')

    def reverse(self, viewname: str, kwargs: dict = None) -> str:
        params = dict(kwargs or {})
        for pattern, _, full_name in self._iter_routes():
            if full_name != viewname:
                continue
            used = set()
            def repl(m):
                conv_type, pname = m.group(1), m.group(2)
                if pname not in params:
                    raise NoReverseMatch(f'Missing param {pname}')
                val = params[pname]
                if conv_type == 'int' and (not isinstance(val, int) or isinstance(val, bool) or val < 0):
                    raise NoReverseMatch(f'Invalid int param {pname}')
                if conv_type == 'str' and (not str(val) or '/' in str(val)):
                    raise NoReverseMatch(f'Invalid str param {pname}')
                used.add(pname)
                return str(val)
            result = re.sub(r'<(int|str):([a-zA-Z_][a-zA-Z0-9_]*)>', repl, pattern)
            if set(params.keys()) != used:
                raise NoReverseMatch('Unexpected kwargs')
            return result
        raise NoReverseMatch(f'Route {viewname} not found')

