class MiniQuerySet:
    def __init__(self, db, select=None, prefetch=None):
        self.db = db
        self._select = list(select or [])
        self._prefetch = list(prefetch or [])

    def select_related(self, field: str):
        return MiniQuerySet(self.db, self._select + [field], self._prefetch)

    def prefetch_related(self, field: str):
        return MiniQuerySet(self.db, self._select, self._prefetch + [field])

    def all(self) -> list:
        orders = self.db.query_orders(join_fields=self._select)
        result = [dict(o) for o in orders]
        if result and 'items' in self._prefetch:
            ids = [o['id'] for o in result]
            items_by_order = self.db.query_items_in(ids)
            for o in result:
                o['items'] = list(items_by_order.get(o['id'], []))
        return result

