    def __init__(self, repo, oid, cached):
        self.repo, self.oid, self.cached = repo, oid, cached
    def filter(self, **kw):
        self.repo.sql_count += 1
        return [it for it in self.repo._items[self.oid] if all(it.get(k) == v for k, v in kw.items())]
class OrderObj:
