        self.lookup = lookup
        self.queryset = queryset
        self.to_attr = to_attr

def get_active_order_items(repo) -> list:
    pf = Prefetch('items', queryset=repo.item_qs().filter(active=True), to_attr='active_items')
    orders = repo.orders().prefetch_related(pf).all()
    return [
        {'order_id': o.id, 'skus': [it['sku'] for it in o.active_items]}
        for o in orders
    ]

