def run_hybrid_stack(middlewares: list, view_is_async: bool, view_fn) -> dict:
    for mw in middlewares:
        if not mw.get('sync_capable') and not mw.get('async_capable'):
            raise ValueError(f"Middleware {mw.get('name')} supports neither sync nor async")
    current_async = view_is_async
    switches = 0
    for mw in reversed(middlewares):
        if current_async and not mw.get('async_capable'):
            current_async = False
            switches += 1
        elif not current_async and not mw.get('sync_capable'):
            current_async = True
            switches += 1
    headers = {}
    try:
        status = view_fn()
    except Exception:
        status = 500
    finally:
        for mw in reversed(middlewares):
            headers.update(mw.get('security_headers', {}))
    return {'status': status, 'headers': headers, 'adapter_switches': switches}

