class DefaultRouter:
    def __init__(self):
        self.routes = []

    def register(self, prefix: str, viewset_cls):
        p = prefix.strip('/')
        crud = [
            ('GET', f'/{p}/', 'list'),
            ('POST', f'/{p}/', 'create'),
            ('GET', f'/{p}/<pk>/', 'retrieve'),
            ('PUT', f'/{p}/<pk>/', 'update'),
            ('PATCH', f'/{p}/<pk>/', 'partial_update'),
            ('DELETE', f'/{p}/<pk>/', 'destroy'),
        ]
        self.routes.extend(crud)
        for attr_name in dir(viewset_cls):
            fn = getattr(viewset_cls, attr_name)
            meta = getattr(fn, '_action_meta', None)
            if not meta:
                continue
            sub = meta['url_path'].strip('/')
            path = f'/{p}/<pk>/{sub}/' if meta['detail'] else f'/{p}/{sub}/'
            for m in meta['methods']:
                self.routes.append((m, path, attr_name))

