import secrets

class TokenRotationService:
    def __init__(self):
        self._families = {}
        self._tokens = {}

    def _mint(self, user_id: str, family_id: str) -> dict:
        jti = secrets.token_hex(16)
        access = f'acc.{user_id}.{secrets.token_hex(8)}'
        self._tokens[jti] = {'family_id': family_id, 'user_id': user_id, 'used': False}
        self._families[family_id]['active_jti'] = jti
        return {
            'access': access,
            'refresh': {'jti': jti, 'family_id': family_id, 'user_id': user_id},
        }

    def issue_pair(self, user_id: str) -> dict:
        family_id = secrets.token_hex(12)
        self._families[family_id] = {'user_id': user_id, 'revoked': False, 'active_jti': None}
        return self._mint(user_id, family_id)

    def refresh(self, refresh_token: dict) -> dict:
        jti = refresh_token.get('jti')
        family_id = refresh_token.get('family_id')
        fam = self._families.get(family_id)
        rec = self._tokens.get(jti)
        if fam is None or rec is None or rec['family_id'] != family_id or fam['revoked']:
            raise PermissionError('Revoked or unknown token')
        if rec['used']:
            fam['revoked'] = True
            raise PermissionError('Refresh token reuse detected')
        rec['used'] = True
        return self._mint(rec['user_id'], family_id)

    def is_family_revoked(self, family_id: str) -> bool:
        fam = self._families.get(family_id)
        return True if fam is None else fam['revoked']

