import base64
import hashlib
import hmac
import secrets

class OAuthPKCEServer:
    def __init__(self, code_ttl: int = 60):
        self.code_ttl = code_ttl
        self._codes = {}

    @staticmethod
    def _s256(verifier: str) -> str:
        digest = hashlib.sha256(verifier.encode('ascii')).digest()
        return base64.urlsafe_b64encode(digest).rstrip(b'=').decode('ascii')

    def authorize(self, client_id: str, redirect_uri: str, code_challenge: str, state: str, now: int) -> dict:
        if not state or not code_challenge:
            raise ValueError('state and code_challenge are required')
        code = secrets.token_urlsafe(16)
        self._codes[code] = {
            'client_id': client_id,
            'redirect_uri': redirect_uri,
            'code_challenge': code_challenge,
            'expires_at': now + self.code_ttl,
            'used': False,
        }
        return {'code': code, 'state': state}

    def exchange(self, code: str, client_id: str, redirect_uri: str, code_verifier: str, expected_state: str, actual_state: str, now: int) -> dict:
        if not expected_state or not hmac.compare_digest(expected_state, actual_state):
            raise ValueError('CSRF state mismatch')
        rec = self._codes.get(code)
        if rec is None or rec['used'] or now > rec['expires_at']:
            raise ValueError('Invalid or expired code')
        if rec['client_id'] != client_id or rec['redirect_uri'] != redirect_uri:
            raise ValueError('Client binding mismatch')
        if not hmac.compare_digest(self._s256(code_verifier), rec['code_challenge']):
            raise ValueError('PKCE verification failed')
        rec['used'] = True
        return {'access_token': f'at_{secrets.token_hex(12)}', 'token_type': 'Bearer'}

