import secrets

class SessionStore:
    def __init__(self, ttl: int = 3600):
        self.ttl = ttl
        self._sessions = {}
        self._user_index = {}

    def create(self, user_id: str, data: dict, now: int) -> str:
        sid = secrets.token_urlsafe(24)
        self._sessions[sid] = {
            'user_id': user_id,
            'data': dict(data),
            'expires_at': now + self.ttl,
        }
        self._user_index.setdefault(user_id, set()).add(sid)
        return sid

    def get(self, session_id: str, now: int):
        rec = self._sessions.get(session_id)
        if rec is None:
            return None
        if now >= rec['expires_at']:
            self.revoke(session_id)
            return None
        rec['expires_at'] = now + self.ttl
        return dict(rec['data'])

    def revoke(self, session_id: str) -> bool:
        rec = self._sessions.pop(session_id, None)
        if rec is None:
            return False
        sids = self._user_index.get(rec['user_id'])
        if sids is not None:
            sids.discard(session_id)
        return True

    def revoke_all(self, user_id: str) -> int:
        sids = list(self._user_index.pop(user_id, set()))
        count = 0
        for sid in sids:
            if self._sessions.pop(sid, None) is not None:
                count += 1
        return count

    def list_active(self, user_id: str, now: int) -> list:
        sids = list(self._user_index.get(user_id, set()))
        active = []
        for sid in sids:
            rec = self._sessions.get(sid)
            if rec is None or now >= rec['expires_at']:
                self.revoke(sid)
            else:
                active.append(sid)
        return active

