import hashlib
import hmac

def verify_api_key(raw_key: str, required_scope: str, key_store: dict, now: int) -> dict:
    if '.' not in raw_key:
        raise PermissionError('Malformed key')
    prefix, _ = raw_key.split('.', 1)
    rec = key_store.get(prefix)
    if rec is None:
        raise PermissionError('Unknown key')
    digest = hashlib.sha256(raw_key.encode('utf-8')).hexdigest()
    if not hmac.compare_digest(digest, rec['sha256']):
        raise PermissionError('Invalid key secret')
    if rec.get('revoked_at') is not None:
        raise PermissionError('Key revoked')
    exp = rec.get('expires_at')
    if exp is not None and now >= exp:
        raise PermissionError('Key expired')
    if required_scope not in rec.get('scopes', ()):
        raise PermissionError('Insufficient scope')
    return {'prefix': prefix, 'owner': rec['owner'], 'scopes': list(rec['scopes'])}

