class ClusterSimulator:
    def __init__(self, n_instances: int, shared_store: bool = False):
        if n_instances < 1:
            raise ValueError('Need >= 1 instance')
        self.n = n_instances
        self.shared_store = shared_store
        self._locals = [{} for _ in range(n_instances)]
        self._shared = {}
        self._rr = 0
        self._seq = 0

    def _next_node(self) -> int:
        idx = self._rr % self.n
        self._rr += 1
        return idx

    def login(self, user_id: str) -> str:
        idx = self._next_node()
        self._seq += 1
        sid = f'sid-{self._seq}'
        if self.shared_store:
            self._shared[sid] = user_id
        else:
            self._locals[idx][sid] = user_id
        return sid

    def request(self, session_id: str) -> bool:
        idx = self._next_node()
        store = self._shared if self.shared_store else self._locals[idx]
        return session_id in store

