import hashlib

class StickyBalancer:
    def __init__(self, nodes: list, max_load_per_node: int):
        self.nodes = list(nodes)
        self.max_load = max_load_per_node
        self._down = set()
        self._draining = set()
        self._load = {n: 0 for n in self.nodes}
        self._sticky = {}

    def mark_down(self, node: str) -> None:
        self._down.add(node)

    def start_drain(self, node: str) -> None:
        self._draining.add(node)

    def _eligible(self, node: str) -> bool:
        return node not in self._down and node not in self._draining and self._load[node] < self.max_load

    def route(self, client_key: str) -> str:
        pinned = self._sticky.get(client_key)
        if pinned is not None and self._eligible(pinned):
            self._load[pinned] += 1
            return pinned
        candidates = [n for n in self.nodes if self._eligible(n)]
        if not candidates:
            raise RuntimeError('No healthy nodes available')
        h = int(hashlib.sha256(client_key.encode('utf-8')).hexdigest(), 16)
        chosen = min(candidates, key=lambda n: (self._load[n], (self.nodes.index(n) - h) % len(self.nodes)))
        self._sticky[client_key] = chosen
        self._load[chosen] += 1
        return chosen

    def release(self, node: str) -> None:
        if node in self._load and self._load[node] > 0:
            self._load[node] -= 1

