import hashlib
import hmac
import secrets

class PasswordManager:
    def __init__(self, iterations: int = 100000):
        self.iterations = iterations

    def hash_password(self, password: str) -> str:
        salt = secrets.token_bytes(16)
        dk = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, self.iterations)
        return f'pbkdf2_sha256${self.iterations}${salt.hex()}${dk.hex()}'

    def verify_password(self, password: str, stored: str) -> bool:
        parts = stored.split('$')
        if len(parts) != 4 or parts[0] != 'pbkdf2_sha256':
            return False
        try:
            iters = int(parts[1])
            salt = bytes.fromhex(parts[2])
        except ValueError:
            return False
        dk = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, iters).hex()
        return hmac.compare_digest(dk, parts[3])

    def needs_rehash(self, stored: str) -> bool:
        parts = stored.split('$')
        if len(parts) != 4 or parts[0] != 'pbkdf2_sha256':
            return True
        try:
            return int(parts[1]) < self.iterations
        except ValueError:
            return True

