class ProfileCache:
    def __init__(self, db, ttl: int = 300, neg_ttl: int = 30, max_jitter: int = 20):
        self.db = db
        self.ttl = ttl
        self.neg_ttl = neg_ttl
        self.max_jitter = max_jitter
        self.cache = {}

    def _jitter(self, key: str) -> int:
        if self.max_jitter <= 0:
            return 0
        return int(hashlib.sha256(key.encode('utf-8')).hexdigest()[:8], 16) % (self.max_jitter + 1)

    def get_profile(self, user_id: str, now: int):
        rec = self.cache.get(user_id)
        if rec is not None and now < rec['exp']:
            return None if rec['val'] is _MISSING else rec['val']
        val = self.db.find(user_id)
        if val is None:
            self.cache[user_id] = {'val': _MISSING, 'exp': now + self.neg_ttl}
            return None
        self.cache[user_id] = {'val': val, 'exp': now + self.ttl + self._jitter(user_id)}
        return val

    def update_email(self, user_id: str, email: str) -> None:
        self.db.update(user_id, email)
        self.db.commit()
        self.cache.pop(user_id, None)

