class ResilientHttpClient:
    def __init__(self, transport, connect_timeout: float = 1.0, read_timeout: float = 3.0):
        self.transport = transport
        self.connect_timeout = connect_timeout
        self.read_timeout = read_timeout

    def _can_retry(self, method: str, headers: dict) -> bool:
        if method in IDEMPOTENT_METHODS:
            return True
        return method == 'POST' and bool(headers.get('Idempotency-Key'))

    def request(self, method: str, url: str, headers: dict = None, max_retries: int = 2) -> dict:
        m = method.upper()
        hdrs = dict(headers or {})
        timeout = (self.connect_timeout, self.read_timeout)
        can_retry = self._can_retry(m, hdrs)
        attempts = max_retries + 1 if can_retry else 1
        for attempt in range(attempts):
            resp = None
            try:
                resp = self.transport.send(m, url, hdrs, timeout=timeout)
                if resp.status < 500 or attempt == attempts - 1:
                    return {'status': resp.status, 'body': resp.body}
            except (TimeoutError, ConnectionError):
                if attempt == attempts - 1:
                    raise
            finally:
                if resp is not None:
                    resp.close()

