    def __init__(self, failure_threshold: int, recovery_timeout: int, half_open_max: int = 2):
        self.failure_threshold = failure_threshold
        self.recovery_timeout = recovery_timeout
        self.half_open_max = half_open_max
        self.state = 'CLOSED'
        self._failures = 0
        self._opened_at = 0
        self._half_open_ok = 0

    def call(self, fn, now: int):
        if self.state == 'OPEN':
            if now - self._opened_at >= self.recovery_timeout:
                self.state = 'HALF_OPEN'
                self._half_open_ok = 0
            else:
                raise CircuitOpenError('Circuit is OPEN')
        try:
            res = fn()
        except Exception:
            if self.state == 'HALF_OPEN':
                self.state = 'OPEN'
                self._opened_at = now
                self._half_open_ok = 0
            else:
                self._failures += 1
                if self._failures >= self.failure_threshold:
                    self.state = 'OPEN'
                    self._opened_at = now
            raise
        if self.state == 'HALF_OPEN':
            self._half_open_ok += 1
            if self._half_open_ok >= self.half_open_max:
                self.state = 'CLOSED'
                self._failures = 0
                self._half_open_ok = 0
        else:
            self._failures = 0
        return res

