import json

class WebhookProcessor:
    def __init__(self, secret: str, tolerance_sec: int = 300):
        self.secret = secret
        self.tolerance_sec = tolerance_sec
        self.processed = []
        self._seen = set()

    def process(self, raw_body: bytes, headers: dict, now: int) -> dict:
        try:
            ts = int(headers.get('X-Timestamp', ''))
        except (TypeError, ValueError):
            raise PermissionError('Missing or invalid timestamp')
        if abs(now - ts) > self.tolerance_sec:
            raise PermissionError('Timestamp outside tolerance')
        signed_msg = f'{ts}.'.encode('ascii') + raw_body
        expected = 'sha256=' + hmac.new(self.secret.encode('utf-8'), signed_msg, hashlib.sha256).hexdigest()
        actual = headers.get('X-Signature', '')
        if not hmac.compare_digest(actual, expected):
            raise PermissionError('Bad signature')
        payload = json.loads(raw_body.decode('utf-8'))
        eid = payload['event_id']
        if eid in self._seen:
            return {'status': 'duplicate', 'event_id': eid}
        self._seen.add(eid)
        self.processed.append(eid)
        return {'status': 'processed', 'event_id': eid}

