class RetryQueueWorker:
    def __init__(self, max_retries: int = 3, base_delay: int = 2):
        self.max_retries = max_retries
        self.base_delay = base_delay
        self.queue = []
        self.dlq = []

    def enqueue(self, msg_id: str, payload: dict, now: int = 0) -> None:
        self.queue.append({'id': msg_id, 'payload': dict(payload), 'attempts': 0, 'ready_at': now})

    def process_next(self, handler, now: int) -> str:
        idx = next((i for i, m in enumerate(self.queue) if m['ready_at'] <= now), None)
        if idx is None:
            return 'empty'
        msg = self.queue.pop(idx)
        try:
            handler(msg['payload'])
            return 'ack'
        except Exception as exc:
            msg['attempts'] += 1
            if msg['attempts'] <= self.max_retries:
                delay = self.base_delay * (2 ** (msg['attempts'] - 1))
                msg['ready_at'] = now + delay
                self.queue.append(msg)
                return 'retry'
            self.dlq.append({
                'id': msg['id'],
                'payload': msg['payload'],
                'reason': f'{type(exc).__name__}: {exc}',
                'attempts': msg['attempts'],
            })
            return 'dlq'

    def replay_dlq(self, msg_id: str, now: int = 0) -> bool:
        idx = next((i for i, m in enumerate(self.dlq) if m['id'] == msg_id), None)
        if idx is None:
            return False
        dead = self.dlq.pop(idx)
        self.queue.append({'id': dead['id'], 'payload': dead['payload'], 'attempts': 0, 'ready_at': now})
        return True

