import math

class FixedWindowLimiter:
    def __init__(self, limit: int, window_sec: int):
        self.limit = limit
        self.window_sec = window_sec
        self._counts = {}

    def check(self, key: str, now: float) -> dict:
        win = int(now // self.window_sec)
        reset = (win + 1) * self.window_sec
        cur = self._counts.get((key, win), 0)
        if cur >= self.limit:
            retry = max(1, math.ceil(reset - now))
            return {
                'allowed': False,
                'status': 429,
                'headers': {
                    'X-RateLimit-Limit': str(self.limit),
                    'X-RateLimit-Remaining': '0',
                    'X-RateLimit-Reset': str(reset),
                    'Retry-After': str(retry),
                },
            }
        cur += 1
        self._counts[(key, win)] = cur
        return {
            'allowed': True,
            'status': 200,
            'headers': {
                'X-RateLimit-Limit': str(self.limit),
                'X-RateLimit-Remaining': str(self.limit - cur),
                'X-RateLimit-Reset': str(reset),
            },
        }

class SlidingWindowCounterLimiter:
    def __init__(self, limit: int, window_sec: int):
        self.limit = limit
        self.window_sec = window_sec
        self._counts = {}

    def check(self, key: str, now: float) -> dict:
        win = int(now // self.window_sec)
        win_start = win * self.window_sec
        reset = win_start + self.window_sec
        weight_prev = 1.0 - (now - win_start) / self.window_sec
        prev_cnt = self._counts.get((key, win - 1), 0)
        cur_cnt = self._counts.get((key, win), 0)
        est = prev_cnt * weight_prev + cur_cnt
        if est + 1 > self.limit:
            retry = max(1, math.ceil(reset - now))
            return {
                'allowed': False,
                'status': 429,
                'headers': {
                    'X-RateLimit-Limit': str(self.limit),
                    'X-RateLimit-Remaining': '0',
                    'X-RateLimit-Reset': str(reset),
                    'Retry-After': str(retry),
                },
            }
        cur_cnt += 1
        self._counts[(key, win)] = cur_cnt
        remaining = max(0, int(self.limit - (prev_cnt * weight_prev + cur_cnt)))
        return {
            'allowed': True,
            'status': 200,
            'headers': {
                'X-RateLimit-Limit': str(self.limit),
                'X-RateLimit-Remaining': str(remaining),
                'X-RateLimit-Reset': str(reset),
            },
        }

