import hashlib

def stream_upload(chunk_iter, sink, magic_prefix: bytes, max_bytes: int) -> dict:
    hasher = hashlib.sha256()
    total = 0
    header = b''
    checked_magic = False
    for chunk in chunk_iter:
        if not chunk:
            continue
        sink.track_buffer(len(chunk))
        total += len(chunk)
        if total > max_bytes:
            raise ValueError('File too large')
        if not checked_magic:
            header += chunk
            if len(header) >= len(magic_prefix):
                if not header.startswith(magic_prefix):
                    raise ValueError('Invalid magic bytes')
                checked_magic = True
        hasher.update(chunk)
        sink.write(chunk)
    if not checked_magic:
        raise ValueError('Invalid magic bytes')
    return {'size': total, 'sha256': hasher.hexdigest()}

