class Config:
    def __init__(self, values: dict, secret_keys: set):
        self._values = dict(values)
        self._secret_keys = set(secret_keys)

    def get(self, key: str, default=None):
        return self._values.get(key, default)

    def safe_dict(self) -> dict:
        return {k: ('***' if k in self._secret_keys else v) for k, v in self._values.items()}

    def __repr__(self) -> str:
        return f'Config({self.safe_dict()!r})'

class ConfigLoader:
    @staticmethod
    def _parse(val, typ: str):
        if typ == 'str':
            return str(val)
        if typ == 'int':
            return int(val)
        if typ == 'bool':
            if isinstance(val, bool):
                return val
            low = str(val).strip().lower()
            if low in ('true', '1', 'yes'):
                return True
            if low in ('false', '0', 'no'):
                return False
            raise ValueError(f'Invalid bool: {val}')
        if typ == 'list':
            if isinstance(val, list):
                return list(val)
            return [x.strip() for x in str(val).split(',') if x.strip()]
        raise ValueError(f'Unknown type: {typ}')

    def load(self, schema: dict, os_env: dict, dotenv: dict) -> Config:
        values = {}
        secrets_set = set()
        errors = []
        for key, spec in schema.items():
            if spec.get('secret'):
                secrets_set.add(key)
            if key in os_env:
                raw = os_env[key]
            elif key in dotenv:
                raw = dotenv[key]
            elif 'default' in spec:
                raw = spec['default']
            else:
                if spec.get('required', False):
                    errors.append(f'{key}: missing required')
                continue
            try:
                values[key] = self._parse(raw, spec.get('type', 'str'))
            except Exception as exc:
                errors.append(f'{key}: {exc}')
        if errors:
            raise ValueError('; '.join(errors))
        return Config(values, secrets_set)

