import hashlib
import hmac

class KeyRing:
    def __init__(self, initial_kid: str, initial_secret: str):
        self.active_kid = initial_kid
        self._keys = {initial_kid: {'secret': initial_secret, 'grace_until': None, 'revoked': False}}

    @staticmethod
    def _hmac_hex(secret: str, payload: str) -> str:
        return hmac.new(secret.encode('utf-8'), payload.encode('utf-8'), hashlib.sha256).hexdigest()

    def sign(self, payload: str) -> str:
        sec = self._keys[self.active_kid]['secret']
        return f'{self.active_kid}.{self._hmac_hex(sec, payload)}'

    def rotate(self, new_kid: str, new_secret: str, grace_until: int) -> None:
        if new_kid in self._keys:
            raise ValueError('Duplicate kid')
        old = self._keys[self.active_kid]
        old['grace_until'] = grace_until
        self._keys[new_kid] = {'secret': new_secret, 'grace_until': None, 'revoked': False}
        self.active_kid = new_kid

    def revoke(self, kid: str) -> None:
        if kid == self.active_kid:
            raise ValueError('Cannot revoke active key')
        if kid in self._keys:
            self._keys[kid]['revoked'] = True

    def verify(self, payload: str, token: str, now: int) -> bool:
        if '.' not in token:
            return False
        kid, sig = token.split('.', 1)
        rec = self._keys.get(kid)
        if rec is None or rec['revoked']:
            return False
        if kid != self.active_kid:
            if rec['grace_until'] is None or now > rec['grace_until']:
                return False
        expected = self._hmac_hex(rec['secret'], payload)
        return hmac.compare_digest(sig, expected)

