import contextvars
import json

correlation_var = contextvars.ContextVar('correlation_id', default=None)
SENSITIVE_KEYS = {'password', 'token', 'authorization', 'secret'}

def _redact(obj):
    if isinstance(obj, dict):
        out = {}
        for k, v in obj.items():
            if str(k).lower() in SENSITIVE_KEYS:
                out[k] = '***'
            else:
                out[k] = _redact(v)
        return out
    if isinstance(obj, list):
        return [_redact(x) for x in obj]
    return obj

class JsonLogger:
    def log(self, level: str, message: str, extra: dict = None) -> str:
        record = {
            'level': level.upper(),
            'message': message,
            'correlation_id': correlation_var.get(),
            'extra': _redact(extra or {}),
        }
        return json.dumps(record, ensure_ascii=False)

class MetricsRegistry:
    def __init__(self):
        self._counters = {}
        self._histograms = {}

    def inc(self, name: str, value: int = 1) -> None:
        self._counters[name] = self._counters.get(name, 0) + value

    def observe(self, name: str, value: float, buckets: list) -> None:
        h = self._histograms.get(name)
        if h is None:
            h = {'buckets': {b: 0 for b in sorted(buckets)}, '+Inf': 0, 'count': 0, 'sum': 0.0}
            self._histograms[name] = h
        for b in h['buckets']:
            if value <= b:
                h['buckets'][b] += 1
        h['+Inf'] += 1
        h['count'] += 1
        h['sum'] += value

    def snapshot(self) -> dict:
        return {'counters': dict(self._counters), 'histograms': self._histograms}

