class HealthProbeRouter:
    def __init__(self, checks: dict):
        self.checks = dict(checks)
        self.draining = False

    def set_draining(self, flag: bool) -> None:
        self.draining = bool(flag)

    def live(self) -> dict:
        return {'status': 200, 'body': {'status': 'alive'}}

    def ready(self) -> dict:
        deps = {}
        all_ok = True
        for name, fn in self.checks.items():
            try:
                ok = bool(fn())
            except Exception:
                ok = False
            deps[name] = 'ok' if ok else 'fail'
            if not ok:
                all_ok = False
        is_ready = all_ok and not self.draining
        return {
            'status': 200 if is_ready else 503,
            'body': {
                'status': 'ready' if is_ready else 'not_ready',
                'draining': self.draining,
                'deps': deps,
            },
        }

