def _check_type(val, expected_type) -> bool:
    if expected_type is int and isinstance(val, bool):
        return False
    return isinstance(val, expected_type)

def run_contract_suite(app_factory, cases: list) -> dict:
    passed = 0
    failed = []
    for case in cases:
        app = app_factory()
        resp = app.handle(
            case['method'],
            case['path'],
            case.get('headers') or {},
            case.get('body'),
        )
        errs = []
        if resp.get('status') != case['expected_status']:
            errs.append(f"status {resp.get('status')} != {case['expected_status']}")
        body = resp.get('body')
        schema = case.get('expected_schema') or {}
        if schema:
            if not isinstance(body, dict):
                errs.append('body is not a dict')
            else:
                for field, typ in schema.items():
                    if field not in body:
                        errs.append(f'missing field {field}')
                    elif not _check_type(body[field], typ):
                        errs.append(f'field {field} wrong type')
        resp_hdrs = {k.lower(): v for k, v in (resp.get('headers') or {}).items()}
        for hk, hv in (case.get('expected_headers') or {}).items():
            if resp_hdrs.get(hk.lower()) != hv:
                errs.append(f'header {hk} mismatch')
        if errs:
            failed.append({'name': case['name'], 'errors': errs})
        else:
            passed += 1
    return {'total': len(cases), 'passed': passed, 'failed': failed}

